import{c as s,Q as a,j as e,m as d}from"./chunks/framework.DK3sgdKX.js";const k=JSON.parse('{"title":"TH07 第六面移植说明","description":"","frontmatter":{},"headers":[],"relativePath":"TH07_STAGE6_PORT.md","filePath":"TH07_STAGE6_PORT.md","lastUpdated":1795193770000}'),n={name:"TH07_STAGE6_PORT.md"};function o(i,t,p,l,c,r){return a(),e("div",null,[...t[0]||(t[0]=[d(`<h1 id="th07-第六面移植说明" tabindex="-1">TH07 第六面移植说明 <a class="header-anchor" href="#th07-第六面移植说明" aria-label="Permalink to &quot;TH07 第六面移植说明&quot;">​</a></h1><p>本页记录以 PySTG 公开 Python API 移植东方妖妖梦（TH07）第六面的代码结构、Boss 阶段设计、通用引擎接口映射、本地运行方式及已知差异。移植代码位于 <code>game_content/ports/th07_stage6/</code>，复用现有运行时与渲染管线，不包含原作虚拟机或版权素材。</p><h2 id="_1-代码结构" tabindex="-1">1. 代码结构 <a class="header-anchor" href="#_1-代码结构" aria-label="Permalink to &quot;1. 代码结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tools/import_th07_stage6_assets.py   # 从本地原版离线导出图集、音频与静态场景</span></span>
<span class="line"><span>tools/preview_th07_stage6.py         # 启动器，经 main.py 加载 game_content.ports.th07_stage6.entry</span></span>
<span class="line"><span>game_content/ports/th07_stage6/</span></span>
<span class="line"><span>├─ entry.py          # 标准内容入口</span></span>
<span class="line"><span>├─ stage.py          # 整面流程与加载期预热声明</span></span>
<span class="line"><span>├─ road.py           # 47 个道中敌人出生、死亡残影与背景粒子 owner</span></span>
<span class="line"><span>├─ youmu.py          # 中 Boss 妖梦（非符 + 一念无量劫 + 击破/超时退场）</span></span>
<span class="line"><span>├─ yuyuko.py         # 关底幽幽子（10 阶段含墨染与反魂蝶 + 结束演出）</span></span>
<span class="line"><span>├─ common.py         # 源坐标/单位换算、批量发射辅助与内容规则</span></span>
<span class="line"><span>├─ background.py     # 六面 3D 场景、镜头与标签 1–5、eff05/eff06 双层符卡背景、三维落樱</span></span>
<span class="line"><span>├─ titles.py         # 关卡标题、Boss 入场名与 BGM 标题</span></span>
<span class="line"><span>└─ resources.py      # 本地导出缓存加载与资源注册</span></span></code></pre></div><h2 id="_2-关卡流程与-boss-阶段表" tabindex="-1">2. 关卡流程与 Boss 阶段表 <a class="header-anchor" href="#_2-关卡流程与-boss-阶段表" aria-label="Permalink to &quot;2. 关卡流程与 Boss 阶段表&quot;">​</a></h2><p>道中先完成 47 次敌人出场，随后进入中 Boss 妖梦战斗；妖梦退场后触发背景转场并进入幽幽子战与尾声。</p><table tabindex="0"><thead><tr><th>Boss</th><th>阶段</th><th>HP / 切卡阈值</th><th>时限（帧）</th></tr></thead><tbody><tr><td>妖梦</td><td>非符</td><td><code>15000</code>（严格 <code>&lt; 1500</code> 切符卡；超时直接退场）</td><td><code>3600</code></td></tr><tr><td>妖梦</td><td>符卡「一念无量劫」</td><td>继承钳回后的 <code>1500</code></td><td><code>2400</code></td></tr><tr><td>幽幽子</td><td>非符 1 → 亡我乡</td><td><code>21000</code> / 阈值 <code>2100</code>（继承）</td><td><code>3600</code> / <code>3900</code></td></tr><tr><td>幽幽子</td><td>非符 2 → 生者必灭</td><td><code>32000</code> / 阈值 <code>3000</code>（继承）</td><td><code>3600</code> / <code>3900</code></td></tr><tr><td>幽幽子</td><td>非符 3 → 华胥的永眠 / 蝴蝶</td><td><code>32000</code> / 阈值 <code>3000</code>（继承）</td><td><code>3600</code> / <code>3900</code></td></tr><tr><td>幽幽子</td><td>非符 4 → 弘川</td><td><code>22000</code> / 阈值 <code>2200</code>（继承）</td><td><code>3600</code> / <code>3900</code></td></tr><tr><td>幽幽子</td><td>樱符「完全墨染的樱花」</td><td><code>6000</code></td><td><code>5940</code></td></tr><tr><td>幽幽子</td><td>反魂蝶（耐久）</td><td><code>1</code>（不可受伤）</td><td>前奏后重置 <code>4020</code></td></tr></tbody></table><h2 id="_3-通用-runtime-能力映射" tabindex="-1">3. 通用 Runtime 能力映射 <a class="header-anchor" href="#_3-通用-runtime-能力映射" aria-label="Permalink to &quot;3. 通用 Runtime 能力映射&quot;">​</a></h2><p>六面移植推动补齐并使用了以下通用公开接口：</p><table tabindex="0"><thead><tr><th>机制需求</th><th>PySTG 公开入口</th></tr></thead><tbody><tr><td>出生期移动但不碰撞、临时初速与越界宽限</td><td><code>ctx.configure_bullet_birth(group, warmup_frames=..., velocity_boost=..., offscreen_grace_frames=...)</code></td></tr><tr><td>临时速度倍率与角度偏移</td><td><code>ctx.set_bullet_behavior(..., stages=[{&quot;velocity_scale_end&quot;: ..., &quot;angle_offset&quot;: ...}])</code></td></tr><tr><td>全屏淡出闪光（<code>ExIns15</code>）</td><td><code>ctx.flash_screen(rgba, frames)</code></td></tr><tr><td>非符 HP 阈值切卡、HP 继承与延迟宣言</td><td><code>BossPhase(hp_threshold=..., carry_hp=..., transition_rule=..., auto_declaration=False)</code> + <code>boss.declare_spell()</code></td></tr><tr><td>同帧伤害聚合与主/副受弹区（如幽幽子宽受弹带）</td><td><code>actor.set_secondary_hitbox(...)</code> + <code>DamageHit(source, region)</code> + <code>target.damage_batch(hits)</code></td></tr><tr><td>特殊道具标签与选择性交回默认收取</td><td><code>ctx.spawn_item(..., tag=...)</code> + 收集规则返回 <code>False</code> 委派默认逻辑</td></tr><tr><td>3D 静态场景、双层符卡底图与标题文字</td><td><code>ctx.background.set_scene / set_camera / set_fog / set_layers</code>、<code>ctx.show_title</code>、<code>ctx.show_text</code>、<code>ParticlePool(motion=&quot;manual&quot;)</code></td></tr></tbody></table><h2 id="_4-导出本地素材与运行" tabindex="-1">4. 导出本地素材与运行 <a class="header-anchor" href="#_4-导出本地素材与运行" aria-label="Permalink to &quot;4. 导出本地素材与运行&quot;">​</a></h2><p>素材需从用户本机合法持有的 TH07 1.00b 副本离线导出：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 从本机原版导出素材到本地缓存</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/import_th07_stage6_assets.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --game-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&lt;path-to-th07-game-dir&gt;&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --thtk-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&lt;path-to-thtk-bin-dir&gt;&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 启动第六面</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/preview_th07_stage6.py</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. 跳转到幽幽子指定阶段（--phase 从 1 开始，如 6=蝴蝶、9=墨染、10=反魂蝶）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/preview_th07_stage6.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yuyuko</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --phase</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --difficulty</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> normal</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --seed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1337</span></span></code></pre></div><p>可通过 <code>--assets &lt;目录&gt;</code> 或环境变量指定缓存路径，更多导入选项见 <code>python tools/import_th07_stage6_assets.py --help</code>。</p><h2 id="_5-已知差异与未移植部分" tabindex="-1">5. 已知差异与未移植部分 <a class="header-anchor" href="#_5-已知差异与未移植部分" aria-label="Permalink to &quot;5. 已知差异与未移植部分&quot;">​</a></h2><ul><li><strong>对话（MSG）</strong>：原版开场、Boss 战前与尾声台词暂未移植，运行到对话处会显式跳过。</li><li><strong>完整 ANM 与特效细节</strong>：真实原图与主要演出已接入，但部分 ANM 中断、消失淡出动画及原版 400 槽共享特效池尚未逐帧还原。</li><li><strong>出生结束帧与亚帧调度</strong>：出生期为清晰的两段式控制，且弹转敌产生的新敌人固定从下一控制帧开始执行，与原版个别物理帧边界存在细微差别。</li><li><strong>计分、擦弹与原版自机</strong>：完整 CherryMax / 结界机制、矩形擦弹区、原版六自机射击与 Bomb 尚未移植。</li><li><strong>RNG 序列</strong>：未复原全部纯视觉效果对全局 RNG 的消耗，因此不能与原版 replay 逐帧对齐。</li></ul>`,16)])])}const _=s(n,[["render",o]]);export{k as __pageData,_ as default};
